style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
html, body {
        background: linear-gradient(135deg, #6dd5ed, #2193b0) !important;
        background-attachment: fixed !important;
        background-size: cover !important;
        color: #000 !important;
    }

    #container-main, .container-main, .rbx-body, .content, .container-header, .container-footer, .page-content, .game-detail-page {
        background: rgba(255, 255, 255, 0.95) !important;
        border-radius: 12px !important;
        padding: 15px !important;
        box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1) !important;
        color: #000 !important;
    }

    #navigation, .navigation, .header, .footer, .navbar {
        background: transparent !important;
        box-shadow: none !important;
    }

    body, span, p, div, h1, h2, h3, h4, h5, h6, a, li {
        color: #000 !important;
    }

    .ad, .ads-container, .game-cards-container, .promo-container, .abp-container {
        display: none !important;
    }

    img, .avatar-card-image, .avatar-headshot {
        border-radius: 12px !important;
    }

    * {
        transition: all 0.2s ease !important;
    }
}
